use std::fmt;
use std::ops::Deref;

#[derive(Debug, Clone, PartialEq)]
struct Username(String);

impl Username {
    fn new(text: &str) -> Result<Username, String> {
        let name = text.trim().to_lowercase();
        let ok_len = (3..=16).contains(&name.len());
        let ok_chars = name.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_');
        if ok_len && ok_chars { Ok(Username(name)) } else { Err(format!("not a valid username: {text:?}")) }
    }
}

impl Deref for Username {
    type Target = str;
    fn deref(&self) -> &str {
        &self.0
    }
}

impl fmt::Display for Username {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "@{}", self.0)
    }
}

unitTests:
fn takes_str(s: &str) -> usize { s.len() }

test("valid names", || {
    let u = Username::new("  Ada_99 ").unwrap();
    check_eq(format!("{u}"), "@ada_99");
    check_eq(takes_str(&u), 6);
    check(u.starts_with("ada"));
});

test("invalid names", || {
    for bad in ["ab", "this_name_is_far_too_long", "ada lovelace", "adé", ""] {
        check(Username::new(bad).is_err());
    }
});

